  private int sumDownFrom(TreeNode root, Map<Integer, Integer> count) {
    if (root == null)
      return 0;

    final int sum = root.val + sumDownFrom(root.left, count) + sumDownFrom(root.right, count);
    count.merge(sum, 1, Integer::sum);
    return sum;
  }
